#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const long long MODULUS = 1000000007;
    int total_points, factor_value;
    cin >> total_points >> factor_value;

    vector<long long> k_array(total_points);
    for (int i = 0; i < total_points; ++i) {
        k_array[i] = (long long)factor_value * i % total_points;
    }

    if (factor_value == 0) {
        long long result = 1;
        for (int i = 0; i < total_points; ++i) {
            result = (result * total_points) % MODULUS;
        }
        cout << result << "\n";
        return 0;
    } else if (factor_value == 1) {
        long long result = 1;
        for (int i = 0; i < total_points; ++i) {
            result = (result * total_points) % MODULUS;
        }
        cout << result << "\n";
        return 0;
    }

    vector<int> visited_list(total_points, 0);
    vector<int> cycle_count_list(total_points, 0);
    long long answer_value = 1;

    for (int start_idx = 0; start_idx < total_points; ++start_idx) {
        if (visited_list[start_idx]) continue;
        int cycle_length = 1;
        int current_node = start_idx;
        visited_list[current_node] = 1;
        while (!visited_list[k_array[current_node]]) {
            current_node = k_array[current_node];
            visited_list[current_node] = 1;
            cycle_length++;
        }
        cycle_count_list[cycle_length]++;
    }

    for (int size = 2; size < total_points; ++size) {
        if (cycle_count_list[size]) {
            long long total_size = size * cycle_count_list[size] + 1;
            long long power_result = 1;
            long long base = total_size % MODULUS;
            long long exp = cycle_count_list[size];
            long long base_pow = base;
            long long e = exp;
            while (e > 0) {
                if (e & 1) {
                    power_result = (power_result * base_pow) % MODULUS;
                }
                base_pow = (base_pow * base_pow) % MODULUS;
                e >>= 1;
            }
            answer_value = (answer_value * power_result) % MODULUS;
        }
    }

    cout << answer_value << "\n";

    return 0;
}
